package kr.blackwiki.smp;

import com.google.gson.*;
import org.junit.jupiter.api.Test;
import java.net.*;
import java.time.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

class ModerationTest {
 private ChatFilter filter(){return new ChatFilter(List.of("미친","존나","씨발","시발","ㅅㅂ","병신","fuck","fucking","shit"),List.of("시발점"));}
 @Test void requestedExceptionsAreAlwaysAllowedEvenWhenListedAsBlocked(){String s="미친 게임 존나 재미있다";assertEquals(s,filter().apply(s).text());assertFalse(filter().apply(s).changed());}
 @Test void exceptionDoesNotDisableOtherProfanityInSameMessage(){var r=filter().apply("존나 씨발 미친");assertEquals("존나 ** 미친",r.text());assertTrue(r.changed());}
 @Test void punctuationWhitespaceAndZeroWidthCannotSplitKoreanProfanity(){for(String s:List.of("시.발","씨 발","씨\u200b발","씨§a발","ㅅ ㅂ")){var r=filter().apply(s);assertTrue(r.changed(),s);assertFalse(r.text().contains("발"),s);}}
 @Test void compatibilityAndFullWidthLatinAreNormalized(){assertTrue(filter().apply("너 𝕗𝕦𝕔𝕜 뭐야").changed());assertTrue(filter().apply("you Ｆ.Ｕ.Ｃ.Ｋ here").changed());}
 @Test void englishBoundariesDoNotMergeNeighborWordsAcrossSpaces(){assertTrue(filter().apply("you fuck this").changed());assertTrue(filter().apply("you f u c k this").changed());assertFalse(filter().apply("shitake mushroom").changed());}
 @Test void legitimateKoreanWordAndSurroundingFormattingAreKept(){assertEquals("좋은 시발점입니다!",filter().apply("좋은 시발점입니다!").text());assertEquals("A😀 ** B",filter().apply("A😀 씨발 B").text());}
 @Test void invalidAndZeroBanDurationsNeverBecomePermanentBans(){for(String[] a:List.of(new String[]{"0","0","0","0"},new String[]{"-1","0","0","1"},new String[]{"0","24","0","0"},new String[]{"0","0","60","0"},new String[]{"99999999999999999999","0","0","0"})){assertThrows(IllegalArgumentException.class,()->BanLedger.seconds(a[0],a[1],a[2],a[3],3650));}}
 @Test void allBanUnitsAreAddedAndExactExpiryAllowsLogin(){assertEquals(93784,BanLedger.seconds("1","2","3","4",3650));Instant start=Instant.parse("2026-11-03T00:00:00Z");var e=BanLedger.create(UUID.randomUUID(),"Steve","OP","규칙 위반",60,start);assertTrue(e.active(start.plusSeconds(59).toEpochMilli()));assertFalse(e.active(start.plusSeconds(60).toEpochMilli()));}
 @Test void banReasonCannotInjectLinesOrBeEmpty(){var e=BanLedger.create(UUID.randomUUID(),"Steve","OP","테스트\n공지",1,Instant.now());assertEquals("테스트 공지",e.reason());assertThrows(IllegalArgumentException.class,()->BanLedger.create(UUID.randomUUID(),"Steve","OP"," ",1,Instant.now()));}
 @Test void immutableBanSnapshotRemainsSafeForConcurrentLoginReaders(){BanLedger l=new BanLedger();UUID id=UUID.randomUUID();var e=BanLedger.create(id,"S","O","x",60,Instant.now());Map<UUID,BanLedger.Entry> map=new HashMap<>();map.put(id,e);l.replace(map);map.clear();assertNotNull(l.active(id,System.currentTimeMillis()));assertThrows(UnsupportedOperationException.class,()->l.snapshot().clear());}
 @Test void channelRouteCannotBeAnArbitraryUrlOrWebhook(){assertEquals("discord.com",DiscordRelay.endpoint("123456789").getHost());for(String url:List.of("http://discord.com/api/webhooks/123456789/abcdefghijklmnop","https://discord.com.evil.test/api/webhooks/123456789/abcdefghijklmnop","https://discord.com@127.0.0.1/api/webhooks/123456789/abcdefghijklmnop","https://discord.com/api/webhooks/123456789/abcdefghijklmnop?redirect=x"))assertThrows(IllegalArgumentException.class,()->DiscordRelay.endpoint(url));}
 @Test void payloadDisablesAllMentionsAndSurvivesQuotesUnicodeAndNewlines(){var json=JsonParser.parseString(DiscordRelay.payload("@everyone <@123> \"미친\"\n존나")).getAsJsonObject();assertEquals(0,json.getAsJsonObject("allowed_mentions").getAsJsonArray("parse").size());assertTrue(json.getAsJsonArray("embeds").get(0).getAsJsonObject().get("description").getAsString().contains("존나"));assertFalse(json.has("content"));}
 @Test void surrogatePairIsNeverCutByMessageLimit(){String s="x".repeat(1898)+"😀"+"z".repeat(10);String cut=DiscordRelay.clip(s,1900);assertTrue(cut.length()<=1900);assertFalse(Character.isHighSurrogate(cut.charAt(cut.length()-2)));}
 static DiscordRelay.Settings settings(int capacity){return new DiscordRelay.Settings(true,DiscordRelay.endpoint("123456789"),"unit-test-token-123456789",capacity,1000);}
 @Test void rateLimitRetainsOrderedBatchAndUsesRetryAfterSeconds(){List<String> bodies=new ArrayList<>();int[] count={0};DiscordRelay.Transport t=(uri,token,body)->{bodies.add(body);return ++count[0]==1?new DiscordRelay.Reply(429,"{\"retry_after\":2.5}",Map.of()):new DiscordRelay.Reply(200,"{}",Map.of());};try(DiscordRelay relay=new DiscordRelay(settings(10),t,false)){relay.offer("first");relay.offer("second");relay.pump(0);assertEquals(2,relay.queued());relay.pump(2499);assertEquals(1,bodies.size());relay.pump(2500);assertEquals(2,bodies.size());assertEquals(bodies.get(0),bodies.get(1));assertEquals(2,relay.sent.get());assertEquals(0,relay.queued());}}
 @Test void badBotTokenStopsRetryFloodAndBoundedQueueRejectsOverflow(){int[] requests={0};try(DiscordRelay relay=new DiscordRelay(settings(2),(uri,token,body)->{requests[0]++;return new DiscordRelay.Reply(401,"{}",Map.of());},false)){assertTrue(relay.offer("a"));assertTrue(relay.offer("b"));assertFalse(relay.offer("c"));relay.pump(0);relay.pump(100000);assertEquals(1,requests[0]);assertFalse(relay.offer("d"));assertEquals(3,relay.dropped.get());}}
 @Test void reconfigureNeverSendsOldQueuedMessagesToNewConfiguration(){List<String> bodies=new ArrayList<>();try(DiscordRelay relay=new DiscordRelay(settings(10),(uri,token,body)->{bodies.add(body);return new DiscordRelay.Reply(204,"",Map.of());},false)){relay.offer("old");relay.reload(new DiscordRelay.Settings(true,DiscordRelay.endpoint("987654321"),"unit-test-token-123456789",10,1000));relay.offer("new");relay.pump(0);assertFalse(bodies.getFirst().contains("old"));assertTrue(bodies.getFirst().contains("new"));}}
 @Test void apiFailureRetriesAreBoundedWithoutBlockingGameThread(){try(DiscordRelay relay=new DiscordRelay(settings(10),(uri,token,body)->new DiscordRelay.Reply(503,"{}",Map.of()),false)){relay.offer("x");for(int n=0;n<7;n++)relay.pump(n*100000L);assertEquals(1,relay.dropped.get());assertEquals(0,relay.queued());}}
}
